package main
import("testing";"os";"path/filepath";"crypto/ed25519";"crypto/rand";"encoding/base64";"encoding/json";"time";"net/http/httptest";"strings")
func TestJournalRecoversTornWrite(t *testing.T){d:=t.TempDir();s:=&Server{dir:d};state,_:=newState("Mesa","password-12345");if e:=s.commit(state);e!=nil{t.Fatal(e)};f,_:=os.OpenFile(filepath.Join(d,"state.journal"),os.O_APPEND|os.O_WRONLY,0600);f.WriteString("{partial");f.Close();next:=&Server{dir:d};if e:=next.load();e!=nil{t.Fatal(e)};if next.data.State.Draft.Name!="Mesa"{t.Fatal("lost snapshot")};state.Draft.Name="Nueva";if e:=next.commit(state);e!=nil{t.Fatal(e)};last:=&Server{dir:d};if e:=last.load();e!=nil{t.Fatal(e)};if last.data.State.Draft.Name!="Nueva"{t.Fatal("failed to recover")}}
func TestSignedLicenseIdentityAndTamper(t *testing.T){pub,priv,_:=ed25519.GenerateKey(rand.Reader);p:=LicensePayload{SchemaVersion:1,RestaurantID:"restaurant",LicenseID:"license",Modes:[]string{"local"},IssuedAt:time.Now().UTC().Format(time.RFC3339),Customer:"Mesa"};b,_:=json.Marshal(p);l:=&License{Payload:base64.StdEncoding.EncodeToString(b),Signature:base64.StdEncoding.EncodeToString(ed25519.Sign(priv,b))};key:=base64.StdEncoding.EncodeToString(pub);if _,e:=verifyLicense(l,key,"restaurant");e!=nil{t.Fatal(e)};if _,e:=verifyLicense(l,key,"another");e==nil{t.Fatal("accepted another owner")};l.Payload=base64.StdEncoding.EncodeToString([]byte("{}"));if _,e:=verifyLicense(l,key,"restaurant");e==nil{t.Fatal("accepted tampering")}}
func TestCatalogAndNetworkValidation(t *testing.T){s,_:=newState("Mesa","password-12345");if e:=validateCatalog(s.Draft);e!=nil{t.Fatal(e)};if e:=validateSettings(s.Settings);e!=nil{t.Fatal(e)};s.Settings.LocalURL="http://evil.example/menu";if validateSettings(s.Settings)==nil{t.Fatal("accepted external local server")};s.Draft.Dishes=[]Dish{{ID:"d",Name:"Sopa",CategoryID:"missing",PriceCents:100}};if validateCatalog(s.Draft)==nil{t.Fatal("accepted missing category")}}
func TestHTTPAuthorizationAndSetup(t *testing.T){d:=t.TempDir();os.Mkdir(filepath.Join(d,"media"),0700);s:=&Server{dir:d,setupToken:"setup"};r:=httptest.NewRequest("POST","http://menu.test/api/v1/setup",strings.NewReader(`{"name":"Mesa","password":"password-12345","setupToken":"setup"}`));r.Header.Set("Content-Type","application/json");w:=httptest.NewRecorder();s.ServeHTTP(w,r);if w.Code!=201{t.Fatal(w.Code,w.Body.String())};w=httptest.NewRecorder();s.ServeHTTP(w,httptest.NewRequest("GET","http://menu.test/api/v1/state",nil));if w.Code!=401{t.Fatal("private state leaked")}}
